        stage: 'rework_missing_outputs',
        error: fixSummary
    });
    if (interruptedResume.attempted) {
        return { resume: true };
    }
    return { resume: false, result: handleInterruptedRework(tracker, ticketKey, branchName, customParams, statuses) };
