function threadKeyOf(t) {
    if (!t) return null;
    if (t.threadId) return String(t.threadId);
    if (t.rootCommentId !== null && t.rootCommentId !== undefined) return 'c' + t.rootCommentId;
    return null;
}

function threadKeySet(threads) {
    var keys = {};
    (threads || []).forEach(function(t) {
        var k = threadKeyOf(t);
        if (k) keys[k] = true;
    });
    return keys;
}

