   if (id.length > 16) id = id.substring(0, 13) + '...';
   var body = String(t.body || '').split('\n')[0].trim();
   var label = id + (body ? ' — "' + body + '"' : '');
   if (label.length > cap) label = label.substring(0, cap - 3) + '...';
